return {["scripts/actions/spells/blue/sandspin.lua"]={["Path"]="scripts/actions/spells/blue/sandspin.lua",["SHA256"]="8b7b4eefd441d5232f19b60f584d3d2537f2312448b2be249268ef055b2ac7f0",["Text"]="-----------------------------------\n-- Spell: Sandspin\n-- Deals earth damage to enemies within range. Additional Effect: Accuracy Down\n-- Spell cost: 10 MP\n-- Monster Type: Amorphs\n-- Spell Type: Magical (Earth)\n-- Blue Magic Points: 2\n-- Stat Bonus: VIT+1\n-- Level: 1\n-- Casting Time: 1.5 seconds\n-- Recast Time: 9.75 seconds\n-- Magic Bursts on: Scission, Gravitation, Darkness\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params       = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem   = xi.ecosystem.AMORPH\n    params.attackType  = xi.attackType.MAGICAL\n    params.damageType  = xi.damageType.EARTH\n    params.dStat       = xi.mod.INT\n\n    params.ftp0            = 1.0\n    params.dStatMultiplier = 1.0\n    params.baseDamageCap   = 13\n    params.halfThreshold   = 16\n    params.lowThreshold    = -6\n\n    params.int_wsc     = 0.2\n\n    -- Handle damage.\n    local damage = xi.spells.blue.useMagicalSpell(caster, target, spell, params)\n\n    if damage <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.ACCURACY_DOWN, 25, 0, 60 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/sandspray.lua"]={["Path"]="scripts/actions/spells/blue/sandspray.lua",["SHA256"]="7aee474d6d7878f72db81a9376eb4406272c517ae4595414947ca04bb76ee284",["Text"]="-----------------------------------\n-- Spell: Sandspray\n-- Blinds enemies within a fan-shaped area originating from the caster\n-- Spell cost: 43 MP\n-- Monster Type: Beastmen\n-- Spell Type: Magical (Dark)\n-- Blue Magic Points: 2\n-- Stat Bonus: VIT+1\n-- Level: 66\n-- Casting Time: 3 seconds\n-- Recast Time: 90 seconds\n-- Magic Bursts on: Compression, Gravitation, and Darkness\n-- Combos: Clear Mind\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = {}\n    params.ecosystem       = xi.ecosystem.BEASTMEN\n    params.effect          = xi.effect.BLINDNESS\n    params.power           = 25\n    params.tick            = 0\n    params.duration        = 120\n    params.resistThreshold = 0.5\n    params.isGaze          = false\n    params.isConal         = true\n\n    return xi.spells.blue.useEnfeeblingSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/screwdriver.lua"]={["Path"]="scripts/actions/spells/blue/screwdriver.lua",["SHA256"]="3b47032a9f013eecd48abc787a51418ae2c3013a024212d3ca8d180dc1af0553",["Text"]="-----------------------------------\n-- Spell: Screwdriver\n-- Deals critical damage. Chance of critical hit varies with TP\n-- Spell cost: 21 MP\n-- Monster Type: Aquans\n-- Spell Type: Physical (Piercing)\n-- Blue Magic Points: 3\n-- Stat Bonus: VIT+1, CHR+1, HP+10\n-- Level: 26\n-- Casting Time: 0.5 seconds\n-- Recast Time: 14 seconds\n-- Skillchain Element(s): Transfixion/Scission\n-- Combos: Evasion Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params        = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem    = xi.ecosystem.AQUAN\n    params.tpModifier   = xi.spells.blue.tpMod.CRITICAL\n\n    if params.hasAzureLore then\n        params.critChance = 35\n    elseif params.hasChainAffinity then\n        params.critChance = xi.spells.blue.calculatefTP(caster:getTP(), 0, 15, 30)\n    end\n\n    params.attackType      = xi.attackType.PHYSICAL\n    params.damageType      = xi.damageType.PIERCING\n    params.skillchainType  = xi.skillchainType.TRANSFIXION\n    params.skillchainType2 = xi.skillchainType.SCISSION\n\n    params.numHits       = 1\n    params.ftp0          = 1.375\n    params.ftp1500       = 1.375\n    params.ftp3000       = 1.375\n    params.ftpAzure      = 1.375\n    params.baseDamageCap = 27\n    params.attackMult    = 1.6\n\n    params.str_wsc = 0.2\n    params.mnd_wsc = 0.2\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/seedspray.lua"]={["Path"]="scripts/actions/spells/blue/seedspray.lua",["SHA256"]="84437121b24aa353033de7ec9042a412c83e7716a605b31b3e022b33ddfe2b58",["Text"]="-----------------------------------\n-- Spell: Seedspray\n-- Delivers a threefold attack. Additional effect: Weakens defense. Chance of effect varies with TP\n-- Spell cost: 61 MP\n-- Monster Type: Plantoids\n-- Spell Type: Physical (Slashing)\n-- Blue Magic Points: 2\n-- Stat Bonus: VIT+1\n-- Level: 61\n-- Casting Time: 4 seconds\n-- Recast Time: 35 seconds\n-- Skillchain Element(s): Induration/Detonation\n-- Combos: Beast Killer\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem       = xi.ecosystem.PLANTOID\n    params.tpModifier      = xi.spells.blue.tpMod.DURATION\n    params.attackType      = xi.attackType.PHYSICAL\n    params.damageType      = xi.damageType.SLASHING\n    params.skillchainType  = xi.skillchainType.INDURATION\n    params.skillchainType2 = xi.skillchainType.DETONATION\n\n    params.numHits       = 3\n    params.ftp0          = 0.875\n    params.ftp1500       = 0.875\n    params.ftp3000       = 0.875\n    params.ftpAzure      = 0.875\n    params.baseDamageCap = 999 -- uncapped\n\n    params.dex_wsc    = 0.3\n\n    -- Handle damage.\n    local damage = xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\n\n    if params.hitsLanded <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.DEFENSE_DOWN, 8, 0, 120 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/self-destruct.lua"]={["Path"]="scripts/actions/spells/blue/self-destruct.lua",["SHA256"]="a58c292a1ba95fb94847acbbad3128ae50025841c3410838887cf6f5d8a74275",["Text"]="-----------------------------------\n-- Spell: Self-Destruct\n-- Sacrifices HP to damage enemies within range. Affects caster with Weakness\n-- Spell cost: 100 MP\n-- Monster Type: Arcana\n-- Spell Type: Magical (Fire)\n-- Blue Magic Points: 3\n-- Stat Bonus: STR+2\n-- Level: 50\n-- Casting Time: 3.25 seconds\n-- Recast Time: 21 seconds\n-- Magic Bursts on: Liquefaction, Fusion, and Light\n-- Combos: Auto Refresh\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    caster:setLocalVar('selfdestructHp', caster:getHP())\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = xi.spells.blue.getDefaultParams(caster)\n    params.attackType = xi.attackType.MAGICAL\n    params.damageType = xi.damageType.FIRE\n    local playerHP    = caster:getLocalVar('selfdestructHp')\n    local damage      = playerHP - 1\n\n    if damage > 0 then\n        damage = xi.spells.blue.applySpellDamage(caster, target, spell, damage, params)\n        caster:setHP(1)\n        caster:delStatusEffectSilent(xi.effect.WEAKNESS)\n        caster:addStatusEffect(xi.effect.WEAKNESS, { power = 1, duration = 300, origin = caster })\n    else\n        spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/sheep_song.lua"]={["Path"]="scripts/actions/spells/blue/sheep_song.lua",["SHA256"]="11c2013fc4a24af7fc0ee7f02ddf39c983b00c2441316bd77ed4b0093fe290ac",["Text"]="-----------------------------------\n-- Spell: Sheep Song\n-- Puts all enemies within range to sleep\n-- Spell cost: 22 MP\n-- Monster Type: Beasts\n-- Spell Type: Magical (Light)\n-- Blue Magic Points: 2\n-- Stat Bonus: CHR+1, HP+5\n-- Level: 16\n-- Casting Time: Casting Time: 3 seconds\n-- Recast Time: Recast Time: 60 seconds\n-- Duration: 60 seconds\n-- Magic Bursts on: Transfixion, Fusion, and Light\n-- Combos: Auto Regen\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = {}\n    params.ecosystem       = xi.ecosystem.BEAST\n    params.effect          = xi.effect.SLEEP_I\n    params.power           = 1\n    params.tick            = 0\n    params.duration        = 60\n    params.resistThreshold = 0.50\n    params.isGaze          = false\n    params.isConal         = false\n\n    return xi.spells.blue.useEnfeeblingSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/sickle_slash.lua"]={["Path"]="scripts/actions/spells/blue/sickle_slash.lua",["SHA256"]="6b0bcda122f0cdc155018e0d6ca092f5effc443c6143c7cd42abfec794fdf857",["Text"]="-----------------------------------\n-- Spell: Sickle Slash\n-- Deals critical damage. Chance of critical hit varies with TP\n-- Spell cost: 41 MP\n-- Monster Type: Vermin\n-- Spell Type: Physical (Blunt)\n-- Blue Magic Points: 4\n-- Stat Bonus: HP-5, MP+15\n-- Level: 48\n-- Casting Time: 0.5 seconds\n-- Recast Time: 20.5 seconds\n-- Skillchain Element: Compression\n-- Combos: Store TP\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem  = xi.ecosystem.VERMIN\n    params.tpModifier = xi.spells.blue.tpMod.CRITICAL\n\n    if params.hasAzureLore then\n        params.critChance = 35\n    elseif params.hasChainAffinity then\n        params.critChance = xi.spells.blue.calculatefTP(caster:getTP(), 0, 15, 30)\n    end\n\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.HAND_TO_HAND\n    params.skillchainType = xi.skillchainType.COMPRESSION\n\n    params.numHits       = 1\n    params.ftp0          = 1.5\n    params.ftp1500       = 1.5\n    params.ftp3000       = 1.5\n    params.ftpAzure      = 1.5\n    params.baseDamageCap = 49\n    params.attackMult    = 2.1\n\n    params.dex_wsc = 0.5\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/smite_of_rage.lua"]={["Path"]="scripts/actions/spells/blue/smite_of_rage.lua",["SHA256"]="b4cd0e7b89bc417986a6fbe54f861475461d1085eaac52457adc9a39f5568f8f",["Text"]="-----------------------------------\n-- Spell: Smite of Rage\n-- Damage varies with TP\n-- Spell cost: 28 MP\n-- Monster Type: Arcana\n-- Spell Type: Physical (Slashing)\n-- Blue Magic Points: 3\n-- Stat Bonus: AGI+3\n-- Level: 34\n-- Casting Time: 0.5 seconds\n-- Recast Time: 13 seconds\n-- Skillchain Element(s): Detonation\n-- Combos: Undead Killer\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params          = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem      = xi.ecosystem.ARCANA\n    params.tpModifier     = xi.spells.blue.tpMod.DAMAGE\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.SLASHING\n    params.skillchainType = xi.skillchainType.DETONATION\n\n    params.numHits       = 1\n    params.ftp0          = 1.5\n    params.ftp1500       = 2.25\n    params.ftp3000       = 2.5\n    params.ftpAzure      = 2.53125\n    params.baseDamageCap = 35\n    params.attackMult    = 1.3\n\n    params.str_wsc = 0.2\n    params.dex_wsc = 0.2\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/soporific.lua"]={["Path"]="scripts/actions/spells/blue/soporific.lua",["SHA256"]="78b4383e199efa0abb196a81873fe72098496bfe593a584da4594cbc52f22bfe",["Text"]="-----------------------------------\n-- Spell: Soporific\n-- Puts all enemies within range to sleep\n-- Spell cost: 38 MP\n-- Monster Type: Plantoids\n-- Spell Type: Magical (Dark)\n-- Blue Magic Points: 4\n-- Stat Bonus: HP-5, MP+5\n-- Level: 24\n-- Casting Time: 3 seconds\n-- Recast Time: 90 seconds\n-- Duration: 90 seconds\n-- Magic Bursts on: Compression, Gravitation, and Darkness\n-- Combos: Clear Mind\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = {}\n    params.ecosystem       = xi.ecosystem.PLANTOID\n    params.effect          = xi.effect.SLEEP_I\n    params.power           = 2\n    params.tick            = 0\n    params.duration        = 90\n    params.resistThreshold = 0.50\n    params.isGaze          = false\n    params.isConal         = false\n\n    return xi.spells.blue.useEnfeeblingSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/sound_blast.lua"]={["Path"]="scripts/actions/spells/blue/sound_blast.lua",["SHA256"]="5f9c4d69a1b68d2d024f6b7e57983f353159ff26d763d6c9697d7dfc86ee1cf9",["Text"]="-----------------------------------\n-- Spell: Sound Blast\n-- Lowers Intelligence of enemies within range.\n-- Spell cost: 25 MP\n-- Monster Type: Birds\n-- Spell Type: Magical (Fire)\n-- Blue Magic Points: 1\n-- Stat Bonus: None\n-- Level: 32\n-- Casting Time: 4 seconds\n-- Recast Time: 30 seconds\n-- Magic Bursts on: Liquefaction, Fusion, and Light\n-- Combos: Magic Attack Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = {}\n    params.ecosystem       = xi.ecosystem.BIRD\n    params.effect          = xi.effect.INT_DOWN\n    params.power           = 9\n    params.tick            = 0\n    params.duration        = 30\n    params.resistThreshold = 0.5\n    params.isGaze          = false\n    params.isConal         = false\n\n    return xi.spells.blue.useEnfeeblingSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/spinal_cleave.lua"]={["Path"]="scripts/actions/spells/blue/spinal_cleave.lua",["SHA256"]="24fdeaf04b875c176c12910aac9b0020fc0483590fccb5f713b76ad7d8b76bda",["Text"]="-----------------------------------\n-- Spell: Spinal Cleave\n-- Accuracy varies with TP\n-- Spell cost: 61 MP\n-- Monster Type: Undead\n-- Spell Type: Physical (Slashing)\n-- Blue Magic Points: 4\n-- Stat Bonus: VIT+2, INT+1, MND+1\n-- Level: 63\n-- Casting Time: 0.5 seconds\n-- Recast Time: 28.5 seconds\n-- Skillchain Element(s): Scission/Detonation\n-- Combos: Attack Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem  = xi.ecosystem.UNDEAD\n    params.tpModifier = xi.spells.blue.tpMod.ACC\n\n    -- TODO: made up\n    if params.hasAzureLore then\n        params.bonusAcc = 70\n    elseif params.hasChainAffinity then\n        params.bonusAcc = math.floor(caster:getTP() / 50)\n    end\n\n    params.attackType      = xi.attackType.PHYSICAL\n    params.damageType      = xi.damageType.SLASHING\n    params.skillchainType  = xi.skillchainType.SCISSION\n    params.skillchainType2 = xi.skillchainType.DETONATION\n\n    params.numHits       = 1\n    params.ftp0          = 3.0\n    params.ftp1500       = 3.0\n    params.ftp3000       = 3.0\n    params.ftpAzure      = 3.0\n    params.baseDamageCap = 999 -- uncapped\n    params.attackMult    = 1.05\n\n    params.str_wsc = 0.3\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/spiral_spin.lua"]={["Path"]="scripts/actions/spells/blue/spiral_spin.lua",["SHA256"]="24b24c6cf36e144f151dc9f83138a8461c0318cbc2bf76d73b0c1b4db54eb974",["Text"]="-----------------------------------\n-- Spell: Spiral Spin\n-- Chance of effect varies with TP. Additional Effect: Accuracy Down\n-- Spell cost: 39 MP\n-- Monster Type: Vermin\n-- Spell Type: Physical (Slashing)\n-- Blue Magic Points: 3\n-- Stat Bonus: STR+1 HP+5\n-- Level: 60\n-- Casting Time: 4 seconds\n-- Recast Time: 45 seconds\n-- Skillchain property: Transfixion\n-- Combos: Plantoid Killer\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params          = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem      = xi.ecosystem.VERMIN\n    params.tpModifier     = xi.spells.blue.tpMod.DURATION\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.SLASHING\n    params.skillchainType = xi.skillchainType.TRANSFIXION\n\n    params.numHits       = 1\n    params.ftp0          = 2.0\n    params.ftp1500       = 2.0\n    params.ftp3000       = 2.0\n    params.ftpAzure      = 2.0\n    params.baseDamageCap = 999 -- uncapped\n\n    params.agi_wsc = 0.3\n\n    -- Handle damage.\n    local damage = xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\n\n    if params.hitsLanded <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.ACCURACY_DOWN, 15, 0, 60 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/sprout_smack.lua"]={["Path"]="scripts/actions/spells/blue/sprout_smack.lua",["SHA256"]="2d199d10403787fd1ad2d9c64494489131cb3f914768ed7fc5a416027d098da3",["Text"]="-----------------------------------\n-- Spell: Sprout Smack\n-- Additional effect: Slow. Duration of effect varies with TP\n-- Spell cost: 6 MP\n-- Monster Type: Plantoids\n-- Spell Type: Physical (Blunt)\n-- Blue Magic Points: 2\n-- Stat Bonus: MND+1\n-- Level: 4\n-- Casting Time: 0.5 seconds\n-- Recast Time: 7.25 seconds\n-- Skillchain property: Reverberation\n-- Combos: Beast Killer\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params          = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem      = xi.ecosystem.PLANTOID\n    params.tpModifier     = xi.spells.blue.tpMod.DURATION\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.BLUNT\n    params.skillchainType = xi.skillchainType.REVERBERATION\n\n    params.numHits       = 1\n    params.ftp0          = 1.5\n    params.ftp1500       = 1.5\n    params.ftp3000       = 1.5\n    params.ftpAzure      = 1.5\n    params.baseDamageCap = 11\n\n    params.vit_wsc = 0.3\n\n    -- Handle damage.\n    local damage = xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\n\n    if params.hitsLanded <= 0 then\n        return damage\n    end\n\n    local duration = 180\n\n    -- TODO: duration needs verification\n    if params.hasAzureLore then\n        duration = 450\n    elseif params.hasChainAffinity then\n        duration = xi.spells.blue.calculatefTP(caster:getTP(), 180, 360, 400)\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.SLOW, 1500, 0, duration },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/stinking_gas.lua"]={["Path"]="scripts/actions/spells/blue/stinking_gas.lua",["SHA256"]="77e64ba3f869e1015c963a2a397d3520be2884807b9f6a70c908e56b76b22ea1",["Text"]="-----------------------------------\n-- Spell: Stinking Gas\n-- Lowers Vitality of enemies within range\n-- Spell cost: 37 MP\n-- Monster Type: Undead\n-- Spell Type: Magical (Wind)\n-- Blue Magic Points: 2\n-- Stat Bonus: AGI+1\n-- Level: 44\n-- Casting Time: 4 seconds\n-- Recast Time: 60 seconds\n-- Magic Bursts on: Detonation, Fragmentation, and Light\n-- Combos: Auto Refresh\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = {}\n    params.ecosystem       = xi.ecosystem.UNDEAD\n    params.effect          = xi.effect.VIT_DOWN\n    params.power           = 10\n    params.tick            = 0\n    params.duration        = 60\n    params.resistThreshold = 0.5\n    params.isGaze          = false\n    params.isConal         = false\n\n    return xi.spells.blue.useEnfeeblingSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/sub-zero_smash.lua"]={["Path"]="scripts/actions/spells/blue/sub-zero_smash.lua",["SHA256"]="4bc0e48b7dacb8f77e252d205083a083cf82b74d8d1f1f8546a930fad8648e43",["Text"]="-----------------------------------\n-- Spell: Sub-zero Smash\n-- Additional Effect: Paralysis. Damage varies with TP\n-- Spell cost: 44 MP\n-- Monster Type: Aquans\n-- Spell Type: Physical (Blunt)\n-- Blue Magic Points: 4\n-- Stat Bonus: HP+10 VIT+3\n-- Level: 72\n-- Casting Time: 1 second\n-- Recast Time: 30 seconds\n-- Skillchain Element(s): Fragmentation\n-- Combos: Fast Cast\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem      = xi.ecosystem.AQUAN\n    params.tpModifier     = xi.spells.blue.tpMod.DAMAGE\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.BLUNT\n    params.skillchainType = xi.skillchainType.FRAGMENTATION\n    params.dStat          = xi.mod.INT\n\n    params.numHits       = 1\n    params.ftp0          = 2.0\n    params.ftp1500       = 2.0\n    params.ftp3000       = 2.0\n    params.ftpAzure      = 2.0\n    params.baseDamageCap = 999 -- uncapped\n    params.attackMult    = 1.05\n\n    params.vit_wsc = 0.6\n\n    -- Handle damage.\n    local damage = xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\n\n    if params.hitsLanded <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.PARALYSIS, 10, 0, 180 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/sudden_lunge.lua"]={["Path"]="scripts/actions/spells/blue/sudden_lunge.lua",["SHA256"]="3d044f993ed150a6adfea1675c450df292f0d239b3609cf818a23ad8c98f4e8c",["Text"]="-----------------------------------\n-- Spell: Sudden Lunge\n-- Damage varies with TP. Additional effect: \"Stun.\"\n-- Spell cost: 18 MP\n-- Monster Type: Vermin\n-- Spell Type: Physical (Slashing)\n-- Blue Magic Points: 4\n-- Stat Bonus: HP-5 MP-5 DEX+1 AGI+1\n-- Level: 95\n-- Casting Time: 0.5 seconds\n-- Recast Time: 15 seconds\n-- Skillchain Element(s): Detonation\n-- Combos: Store TP\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params          = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem      = xi.ecosystem.VERMIN\n    params.tpModifier     = xi.spells.blue.tpMod.DAMAGE\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.SLASHING\n    params.skillchainType = xi.skillchainType.DETONATION\n    params.dStat          = xi.mod.INT\n\n    params.numHits       = 1\n    params.ftp0          = 1.5\n    params.ftp1500       = 2.5\n    params.ftp3000       = 3\n    params.ftpAzure      = 3.5\n    params.baseDamageCap = 100\n\n    params.agi_wsc    = 0.4\n\n    -- Handle damage.\n    local damage = xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\n\n    if params.hitsLanded <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.STUN, 1, 0, 5 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/tail_slap.lua"]={["Path"]="scripts/actions/spells/blue/tail_slap.lua",["SHA256"]="5bbe53b0ab7a2f0288bcd0810301b7f4cadff10754c7d97630898b4153305410",["Text"]="-----------------------------------\n-- Spell: Tail Slap\n-- Delivers an area attack. Additional effect: \"Stun.\" Damage varies with TP\n-- Spell cost: 77 MP\n-- Monster Type: Beastmen\n-- Spell Type: Physical (Blunt)\n-- Blue Magic Points: 4\n-- Stat Bonus: MND+2\n-- Level: 69\n-- Casting Time: 1 seconds\n-- Recast Time: 28.5 seconds\n-- Skillchain Element: Reverberation\n-- Combos: Store TP\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params          = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem      = xi.ecosystem.BEASTMEN\n    params.tpModifier     = xi.spells.blue.tpMod.ATTACK\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.HAND_TO_HAND\n    params.skillchainType = xi.skillchainType.REVERBERATION\n    params.dStat          = xi.mod.INT\n    params.shadowBehavior = xi.mobskills.shadowBehavior.NUMSHADOWS_3 -- guessed\n\n    params.numHits       = 1\n    params.ftp0          = 1.625\n    params.ftp1500       = 1.625\n    params.ftp3000       = 1.625\n    params.ftpAzure      = 1.625\n    params.baseDamageCap = 999 -- uncapped\n    params.attackMult    = 1.05\n\n    if params.hasAzureLore then\n        params.attackMult = 2.65\n    elseif params.hasChainAffinity then\n        params.attackMult = xi.spells.blue.calculatefTP(caster:getTP(), 1.05, 2.5, 2.60)\n    end\n\n    params.str_wsc = 0.2\n    params.vit_wsc = 0.5\n\n    -- Handle damage.\n    local damage = xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\n\n    if params.hitsLanded <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.STUN, 1, 0, 5 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/temporal_shift.lua"]={["Path"]="scripts/actions/spells/blue/temporal_shift.lua",["SHA256"]="06de69376e65d1f7af39540add050bb19c8c8e4050acdfc7df8e41340b4b41df",["Text"]="-----------------------------------\n-- Spell: Temporal Shift\n-- Enemies within range are temporarily prevented from acting\n-- Spell cost: 48 MP\n-- Monster Type: Luminians\n-- Spell Type: Magical (Lightning)\n-- Blue Magic Points: 5\n-- Stat Bonus: HP+10, MP+15\n-- Level: 73\n-- Casting Time: 0.5 seconds\n-- Recast Time: 120 seconds\n-- Magic Bursts on: Impaction, Fragmentation, and Light\n-- Combos: Attack Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = {}\n    params.ecosystem       = xi.ecosystem.LUMINIAN\n    params.effect          = xi.effect.STUN\n    params.power           = 1\n    params.tick            = 0\n    params.duration        = 5\n    params.resistThreshold = 0.25\n    params.isGaze          = false\n    params.isConal         = false\n\n    return xi.spells.blue.useEnfeeblingSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/terror_touch.lua"]={["Path"]="scripts/actions/spells/blue/terror_touch.lua",["SHA256"]="0bfdaccca91515a5124519c0abda8d879c442e669405b3dca9c732225271e3ad",["Text"]="-----------------------------------\n-- Spell: Terror Touch\n-- Additional effect: Weakens attacks. Accuracy varies with TP\n-- Spell cost: 62 MP\n-- Monster Type: Undead\n-- Spell Type: Physical (Blunt)\n-- Blue Magic Points: 3\n-- Stat Bonus: HP-5 MP+10\n-- Level: 40\n-- Casting Time: 3.25 seconds\n-- Recast Time: 21 seconds\n-- Duration: 60~ seconds\n-- Skillchain Element(s): Compression/Reverberation\n-- Combos: Defense Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem  = xi.ecosystem.UNDEAD\n    params.tpModifier = xi.spells.blue.tpMod.ACC\n\n    -- TODO: this is made up\n    if params.hasAzureLore then\n        params.bonusAcc = 70\n    elseif params.hasChainAffinity then\n        params.bonusAcc = math.floor(caster:getTP() / 50)\n    end\n\n    params.attackType      = xi.attackType.PHYSICAL\n    params.damageType      = xi.damageType.HAND_TO_HAND\n    params.skillchainType  = xi.skillchainType.COMPRESSION\n    params.skillchainType2 = xi.skillchainType.REVERBERATION\n\n    params.numHits       = 1\n    params.ftp0          = 1.5\n    params.ftp1500       = 1.5\n    params.ftp3000       = 1.5\n    params.ftpAzure      = 1.5\n    params.baseDamageCap = 41\n    params.attackMult    = 1.05\n\n    params.dex_wsc = 0.2\n    params.int_wsc = 0.2\n\n    -- Handle damage.\n    local damage = xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\n\n    if params.hitsLanded <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.ATTACK_DOWN, 15, 0, 60 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/thermal_pulse.lua"]={["Path"]="scripts/actions/spells/blue/thermal_pulse.lua",["SHA256"]="ff206d856205bf40a724bfa5d81d0b3626323d85ca12de800fae37a5ffa3cf02",["Text"]="-----------------------------------\n-- Spell: Thermal Pulse\n-- Deals Fire damage to enemies within area of effect. Additional effect: Blindness\n-- Spell cost: 151 MP\n-- Monster Type: Vermin\n-- Spell Type: Magical (FIRE)\n-- Blue Magic Points: 3\n-- Stat Bonus: VIT+2\n-- Level: 86\n-- Casting Time: 5.5 seconds\n-- Recast Time: 70 seconds\n-- Magic Bursts on: None\n-- Combos: Attck Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params       = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem   = xi.ecosystem.VERMIN\n    params.attackType  = xi.attackType.MAGICAL\n    params.damageType  = xi.damageType.FIRE\n    params.dStat       = xi.mod.INT\n\n    params.ftp0            = 2.0\n    params.dStatMultiplier = 4.0 -- https://www.ffxiah.com/forum/topic/30626/the-beast-within-a-guide-to-blue-mage/#spells concurs with https://wiki.ffo.jp/html/22468.html on tp\n    params.baseDamageCap   = 100\n\n    params.vit_wsc = 0.4\n\n    -- Handle damage.\n    local damage = xi.spells.blue.useMagicalSpell(caster, target, spell, params)\n\n    if damage <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.BLINDNESS, 25, 0, 60 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/triumphant_roar.lua"]={["Path"]="scripts/actions/spells/blue/triumphant_roar.lua",["SHA256"]="995ba58c6e9d98e4081f7a5846c6ac96ea14a49326b84b99e83e3f5016135769",["Text"]="-----------------------------------\n-- Spell: Triumphant Roar\n-- Enhances Attack\n-- Spell cost: 36 MP\n-- Monster Type: Demon\n-- Spell Type: Magical (Fire)\n-- Blue Magic Points: 3\n-- Stat Bonus: STR+3\n-- Level: 71\n-- Casting Time: 3 seconds\n-- Recast Time: 90 seconds\n-----------------------------------\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local power    = 15\n    local duration = xi.spells.blue.calculateDurationWithDiffusion(caster, 60)\n\n    if not target:addStatusEffect(xi.effect.ATTACK_BOOST, { power = power, duration = duration, origin = caster }) then\n        spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n    end\n\n    return xi.effect.ATTACK_BOOST\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/uppercut.lua"]={["Path"]="scripts/actions/spells/blue/uppercut.lua",["SHA256"]="255f4a41a42c624ea9dba6065828d6c073091a44b85474530ba47e36e4495d16",["Text"]="-----------------------------------\n-- Spell: Uppercut\n-- Damage varies with TP\n-- Spell cost: 31 MP\n-- Monster Type: Plantoids\n-- Spell Type: Physical (Blunt)\n-- Blue Magic Points: 3\n-- Stat Bonus: STR+2, DEX+1\n-- Level: 38\n-- Casting Time: 0.5 seconds\n-- Recast Time: 17.75 seconds\n-- Skillchain Element(s): Liquefaction/Impaction\n-- Combos: Attack Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem       = xi.ecosystem.PLANTOID\n    params.tpModifier      = xi.spells.blue.tpMod.ATTACK\n    params.attackType      = xi.attackType.PHYSICAL\n    params.damageType      = xi.damageType.HAND_TO_HAND\n    params.skillchainType  = xi.skillchainType.LIQUEFACTION\n    params.skillchainType2 = xi.skillchainType.IMPACTION\n\n    params.numHits       = 1\n    params.ftp0          = 1.5\n    params.ftp1500       = 1.5\n    params.ftp3000       = 1.5\n    params.ftpAzure      = 1.5\n    params.baseDamageCap = 39\n    params.attackMult    = 1.6\n\n    if params.hasAzureLore then\n        params.attackMult = 2.4\n    elseif params.hasChainAffinity then\n        params.attackMult = xi.spells.blue.calculatefTP(caster:getTP(), 1.6, 2, 2.3)\n    end\n\n    params.str_wsc = 0.35\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/venom_shell.lua"]={["Path"]="scripts/actions/spells/blue/venom_shell.lua",["SHA256"]="4c649a8fce99d6871c487b2eac7064b8a3a867dd890df1d8f99c4d38a6ce418e",["Text"]="-----------------------------------\n-- Spell: Venom Shell\n-- Poisons enemies within range and gradually reduces their HP\n-- Spell cost: 86 MP\n-- Monster Type: Aquans\n-- Spell Type: Magical (Water)\n-- Blue Magic Points: 3\n-- Stat Bonus: MND+2\n-- Level: 42\n-- Casting Time: 3 seconds\n-- Recast Time: 45 seconds\n-- Magic Bursts on: Reverberation, Distortion, and Darkness\n-- Combos: Clear Mind\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = {}\n    params.ecosystem       = xi.ecosystem.AQUAN\n    params.effect          = xi.effect.POISON\n    params.power           = 6\n    params.tick            = 0\n    params.duration        = 60\n    params.resistThreshold = 0.5\n    params.isGaze          = false\n    params.isConal         = false\n\n    return xi.spells.blue.useEnfeeblingSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/vertical_cleave.lua"]={["Path"]="scripts/actions/spells/blue/vertical_cleave.lua",["SHA256"]="2f7f35bb42b382d3c1742d61e55255591b7eeba6b6ca80ea8e9e9752ac62dcea",["Text"]="-----------------------------------\n-- Spell: Vertical Cleave\n-- Damage varies with TP\n-- Spell cost: 86 MP\n-- Monster Type: Luminians\n-- Spell Type: Physical (Slashing)\n-- Blue Magic Points: 3\n-- Stat Bonus: VIT+1 HP-5 MP+5\n-- Level: 75\n-- Casting Time: 0.5 seconds\n-- Recast Time: 37.25 seconds\n-- Skillchain Element(s): Gravitation\n-- Combos: Defense Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params          = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem      = xi.ecosystem.LUMINIAN\n    params.tpModifier     = xi.spells.blue.tpMod.ATTACK\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.SLASHING\n    params.skillchainType = xi.skillchainType.GRAVITATION\n\n    params.numHits       = 1\n    params.ftp0          = 3.0\n    params.ftp1500       = 3.0\n    params.ftp3000       = 3.0\n    params.ftpAzure      = 3.0\n    params.baseDamageCap = 89\n    params.attackMult    = 1.05\n\n    if params.hasAzureLore then\n        params.attackMult = 2.25\n    elseif params.hasChainAffinity then\n        params.attackMult = xi.spells.blue.calculatefTP(caster:getTP(), 1.05, 2.1, 2.2)\n    end\n\n    params.str_wsc = 0.5\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/voracious_trunk.lua"]={["Path"]="scripts/actions/spells/blue/voracious_trunk.lua",["SHA256"]="b013108b284be8821d52bfa2779240109585be835a7cc0b6f4465dff763489d4",["Text"]="-----------------------------------\n-- Spell: Voracious Trunk\n-- Steals an enemy's buff\n-- Spell cost: 72 MP\n-- Monster Type: Beasts\n-- Spell Type: Magical (Wind)\n-- Blue Magic Points: 4\n-- Stat Bonus: AGI +2\n-- Level: 72\n-- Casting Time: 10 seconds\n-- Recast Time: 56 seconds\n-- Combos: Auto Refresh\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local stolen = 0\n    local params =\n    {\n        magicalElement = spell:getElement(),\n        actorStat      = xi.mod.INT,\n        skillType      = xi.skill.BLUE_MAGIC,\n        spellGroup     = spell:getSpellGroup(),\n    }\n\n    local resist = xi.combat.magicHitRate.calculateResistRate(caster, target, params)\n\n    if resist >= 0.5 then\n        stolen = caster:stealStatusEffect(target)\n        if stolen ~= 0 then\n            spell:setMsg(xi.msg.basic.MAGIC_STEAL)\n        else\n            spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n        end\n    else\n        spell:setMsg(xi.msg.basic.MAGIC_RESIST)\n    end\n\n    return stolen\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/warm-up.lua"]={["Path"]="scripts/actions/spells/blue/warm-up.lua",["SHA256"]="71e5db655cadcea2a3c73dcce5d71dcc1f7fcd7d8d19be5ff7236e95ffe819df",["Text"]="-----------------------------------\n-- Spell: Warm-Up\n-- Enhances accuracy and evasion\n-- Spell cost: 59 MP\n-- Monster Type: Beastmen\n-- Spell Type: Magical (Earth)\n-- Blue Magic Points: 4\n-- Stat Bonus: VIT+1\n-- Level: 68\n-- Casting Time: 7 seconds\n-- Recast Time: 120 seconds\n-- Duration: 180 seconds\n-----------------------------------\n-- Combos: Clear Mind\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local duration     = xi.spells.blue.calculateDurationWithDiffusion(caster, 180)\n    local returnEffect = xi.effect.ACCURACY_BOOST\n\n    local actionOne = target:addStatusEffect(xi.effect.ACCURACY_BOOST, { power = 10, duration = duration, origin = caster })\n    local actionTwo = target:addStatusEffect(xi.effect.EVASION_BOOST, { power = 10, duration = duration, origin = caster })\n\n    if not actionOne and not actionTwo then -- both statuses fail to apply\n        spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n    elseif not actionOne and actionTwo then -- the first status fails to apply\n        returnEffect = xi.effect.EVASION_BOOST\n    elseif actionOne and not actionTwo then -- the second status fails to apply\n        returnEffect = xi.effect.ACCURACY_BOOST\n    end\n\n    return returnEffect\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/whirl_of_rage.lua"]={["Path"]="scripts/actions/spells/blue/whirl_of_rage.lua",["SHA256"]="1a2573c45a831eef47ced103c3465ebcbfff18b10b9249db2c06aa20e2021d7b",["Text"]="-----------------------------------\n-- Spell: Whirl Of Rage\n-- Delivers an area attack that stuns enemies. Damage varies with TP.\n-- Spell cost: 73 MP\n-- Monster Type: Arcana\n-- Spell Type: Physical (Slashing)\n-- Blue Magic Points: 2\n-- Stat Bonus: STR+2 DEX+2\n-- Level: 83\n-- Casting Time: 1 second\n-- Recast Time: 30 seconds\n-- Skillchain Element(s): Scission, Detonation\n-- Combos: Zanshin\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem       = xi.ecosystem.ARCANA\n    params.tpModifier      = xi.spells.blue.tpMod.DURATION\n    params.attackType      = xi.attackType.PHYSICAL\n    params.damageType      = xi.damageType.SLASHING\n    params.skillchainType  = xi.skillchainType.SCISSION\n    params.skillchainType2 = xi.skillchainType.DETONATION\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.NUMSHADOWS_3 -- guessed\n\n    params.numHits       = 1\n    params.ftp0          = 3.0\n    params.ftp1500       = 3.5\n    params.ftp3000       = 4.0\n    params.ftpAzure      = 4.25\n    params.baseDamageCap = 83\n\n    params.str_wsc = 0.3\n    params.mnd_wsc = 0.3\n\n    -- Handle damage.\n    local damage = xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\n\n    if params.hitsLanded <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.STUN, 1, 0, 5 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/white_wind.lua"]={["Path"]="scripts/actions/spells/blue/white_wind.lua",["SHA256"]="1d5fae6f77c658b6f30b9480de25e12d846c40fae2884b9f6e9c33cde6427ec3",["Text"]="-----------------------------------\n-- Spell: White Wind\n-- Restores HP of all party members within area of effect.\n-- Spell cost: 145 MP\n-- Monster Type: Dragon\n-- Spell Type: Magical (Wind)\n-- Blue Magic Points: 5\n-- Stat Bonus: HP+5 AGI+1\n-- Level: 94\n-- Casting Time: 7 seconds\n-- Recast Time: 20 seconds\n-----------------------------------\n-- Combos: Auto Regen\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    -- Need to confirm increases by Divine Seal and Cure Potency equipment\n    local params = {}\n\n    params.minCure         = math.floor(caster:getMaxHP() / 7) * 2\n    params.divisor0        = 0.6666\n    params.constant0       = -45\n    params.powerThreshold1 = 0\n    params.divisor1        = 2\n    params.constant1       = 65\n    params.powerThreshold2 = 0\n    params.divisor2        = 6.5\n    params.constant2       = 144.6666\n\n    return xi.spells.blue.useCuringSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/wild_carrot.lua"]={["Path"]="scripts/actions/spells/blue/wild_carrot.lua",["SHA256"]="bba8b29f913145c763a8f54689087485b5ef0fa38cb201eb4434af3a8ad78258",["Text"]="-----------------------------------\n-- Spell: Wild Carrot\n-- Restores HP for the target party member\n-- Spell cost: 37 MP\n-- Monster Type: Beasts\n-- Spell Type: Magical (Light)\n-- Blue Magic Points: 3\n-- Stat Bonus: HP+5\n-- Level: 30\n-- Casting Time: 2.5 seconds\n-- Recast Time: 6 seconds\n-----------------------------------\n-- Combos: Resist Sleep\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params = {}\n\n    params.minCure         = 120\n    params.divisor0        = 1\n    params.constant0       = 60\n    params.powerThreshold1 = 179\n    params.divisor1        = 2\n    params.constant1       = 105\n    params.powerThreshold2 = 299\n    params.divisor2        = 15.6666\n    params.constant2       = 170.43\n\n    return xi.spells.blue.useCuringSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/wild_oats.lua"]={["Path"]="scripts/actions/spells/blue/wild_oats.lua",["SHA256"]="6e961102c79b5b3a5a11d7d6e7fe6b0f2f378888faad13b709612ca3c9586edb",["Text"]="-----------------------------------\n-- Spell: Wild Oats\n-- Additional effect: Vitality Down. Duration of effect varies on TP\n-- Spell cost: 9 MP\n-- Monster Type: Plantoids\n-- Spell Type: Physical (Piercing)\n-- Blue Magic Points: 3\n-- Stat Bonus: CHR+1, HP+10\n-- Level: 4\n-- Casting Time: 0.5 seconds\n-- Recast Time: 7.25 seconds\n-- Skillchain Element(s): Transfixion\n-- Combos: Beast Killer\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params          = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem      = xi.ecosystem.PLANTOID\n    params.tpModifier     = xi.spells.blue.tpMod.DURATION\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.PIERCING\n    params.skillchainType = xi.skillchainType.TRANSFIXION\n\n    params.numHits       = 1\n    params.ftp0          = 1.8359375\n    params.ftp1500       = 1.8359375\n    params.ftp3000       = 1.8359375\n    params.ftpAzure      = 1.8359375\n    params.baseDamageCap = 11\n\n    params.agi_wsc = 0.3\n\n    -- Handle damage.\n    local damage = xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\n\n    if params.hitsLanded <= 0 then\n        return damage\n    end\n\n    local duration = 180\n\n    -- TODO: duration needs verification\n    if params.hasAzureLore then\n        duration = 450\n    elseif params.hasChainAffinity then\n        duration = xi.spells.blue.calculatefTP(caster:getTP(), 180, 360, 400)\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.VIT_DOWN, 9, 6, duration },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/wind_breath.lua"]={["Path"]="scripts/actions/spells/blue/wind_breath.lua",["SHA256"]="8108da3af7e2cca7265bae9ca56215ba1fcbd1fc7eeae137ea58c6be5daac920",["Text"]="-----------------------------------\n-- Spell: Wind Breath\n-- Deals Wind breath damage to enemies within a fan-shaped area originating from the caster.\n-- Spell cost: 26 MP\n-- Monster Type: Dragons\n-- Spell Type: Magical (Wind)\n-- Blue Magic Points: 2\n-- Stat Bonus: STR+2 AGI+2\n-- Level: 99\n-- Casting Time: 1.5 seconds\n-- Recast Time: 29.5 seconds\n-- Magic Bursts on: None\n-- Combos: Fast Cast\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = {}\n    params.ecosystem  = xi.ecosystem.DRAGON\n    params.attackType = xi.attackType.BREATH\n    params.damageType = xi.damageType.WIND\n    params.hpMod      = 4\n    params.lvlMod     = 0\n    params.isConal    = true\n\n    return xi.spells.blue.useBreathSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/yawn.lua"]={["Path"]="scripts/actions/spells/blue/yawn.lua",["SHA256"]="c6043fd29fb4bb5ce08eae84380039fd10983d4fe1144b104dd2aa7afd06224e",["Text"]="-----------------------------------\n-- Spell: Yawn\n-- Puts all enemies within range to sleep\n-- Spell cost: 55 MP\n-- Monster Type: Birds\n-- Spell Type: Magical (Light)\n-- Blue Magic Points: 3\n-- Stat Bonus: CHR+1, HP+5\n-- Level: 64\n-- Casting Time: 3 seconds\n-- Recast Time: 60 seconds\n-- Duration: 90 seconds\n-- Magic Bursts on: Transfixion, Fusion, Light\n-- Combos: Resist Sleep\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = {}\n    params.ecosystem       = xi.ecosystem.BIRD\n    params.effect          = xi.effect.SLEEP_I\n    params.power           = 2\n    params.tick            = 0\n    params.duration        = 90\n    params.resistThreshold = 0.5\n    params.isGaze          = true\n    params.isConal         = false\n\n    return xi.spells.blue.useEnfeeblingSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"}};
